     3	// findHighlightIndex maps a deep-link target sequence to a step index.
     4	//
     5	// The replay builder uses a stacked model where wrapper steps like `run` and
     6	// `scoring` open first and then extend their completed_sequence over every
     7	// nested event — so a naive "first range that contains target" pick would
     8	// always return the outermost wrapper. We instead prefer:
     9	//
    10	//   1. Exact match on started_sequence.
    11	//   2. Among steps whose [started, completed] range contains the target, the
    12	//      one with the narrowest range (innermost step). Ties broken by latest
    13	//      started_sequence so deeper nesting still wins.
    14	//   3. When nothing contains the target, the nearest earlier step — but only
    15	//      if the target is within the currently-loaded window. Otherwise return
    16	//      -1 and let the UI signal that the target is out of range, rather than
    17	//      highlighting an unrelated early card.
    18	export function findHighlightIndex(
    19	  steps: ReplayStep[],
    20	  target: number,
    21	): number {
    22	  if (!Number.isFinite(target) || steps.length === 0) return -1;
    23	
    24	  let best = -1;
    25	  let bestSpan = Number.POSITIVE_INFINITY;
    26	  let fallback = -1;
    27	  let maxSequence = Number.NEGATIVE_INFINITY;
    28	
    29	  for (let i = 0; i < steps.length; i++) {
    30	    const step = steps[i];
    31	    if (step.started_sequence === target) return i;
    32	
    33	    const endSeq = step.completed_sequence ?? step.started_sequence;
    34	    if (endSeq > maxSequence) maxSequence = endSeq;
    35	
    36	    const contains =
    37	      step.started_sequence <= target && target <= endSeq;
    38	    if (contains) {
    39	      const span = endSeq - step.started_sequence;
    40	      if (span < bestSpan) {
    41	        bestSpan = span;
    42	        best = i;
    43	      } else if (span === bestSpan && step.started_sequence > steps[best].started_sequence) {
    44	        // Same-span tie: prefer the later start — that's the deeper nested
    45	        // step in the stacked wrapper model.
    46	        best = i;
    47	      }
    48	    }
    49	
    50	    if (step.started_sequence <= target) fallback = i;
    51	  }
    52	
    53	  if (best >= 0) return best;
    54	  // Only fall back when the target is inside the loaded window. Beyond it,
    55	  // we have no way to tell which later-loaded step owns the sequence, so
    56	  // highlighting the last-seen early step would be actively misleading.
    57	  if (target > maxSequence) return -1;
    58	  return fallback;
    59	}

